package gen

import (
	"bytes"
	"encoding/json"
	"fmt"
	"maps"
	"regexp"
	"slices"
	"strconv"
	"strings"
)

// Header is the first line of the generated file; scripts/ci/lib.sh
// recognizes it as generated code.
const Header = "// Code generated by tools/genprotocol from metaModel.json; " +
	"DO NOT EDIT."

func (g *generator) emit(consts []byte) ([]byte, error) {
	var w bytes.Buffer
	w.WriteString(Header + "\n\n")
	fmt.Fprintf(&w, "// LSP %s types for the methods in tools/genprotocol"+
		"/gen.Methods.\n\n", g.m.MetaData.Version)
	w.WriteString("package protocol\n\nimport \"encoding/json\"\n\n")
	fmt.Fprintf(&w, "// Version is the LSP version of metaModel.json.\n"+
		"const Version = %q\n\n", g.m.MetaData.Version)
	w.Write(consts)

	w.WriteString("// DocumentURI is a document URI (LSP DocumentUri).\n" +
		"type DocumentURI string\n\n" +
		"// URI is any URI (LSP URI).\ntype URI string\n\n")

	for _, name := range slices.Sorted(maps.Keys(g.enumUse)) {
		if err := g.emitEnum(&w, g.enums[name]); err != nil {
			return nil, fmt.Errorf("enumeration %s: %w", name, err)
		}
	}
	for _, name := range slices.Sorted(maps.Keys(g.alias)) {
		a := g.alias[name]
		comment(&w, "", name+": "+a.doc, a.deprecated)
		fmt.Fprintf(&w, "type %s = %s\n\n", name, a.goType)
	}
	for _, name := range slices.Sorted(maps.Keys(g.decls)) {
		emitStruct(&w, g.decls[name])
	}
	shapes := map[string]bool{}
	for _, name := range slices.Sorted(maps.Keys(g.ors)) {
		if err := g.emitOr(&w, g.ors[name], shapes); err != nil {
			return nil, fmt.Errorf("or type %s: %w", name, err)
		}
	}
	for _, name := range slices.Sorted(maps.Keys(shapes)) {
		g.emitShape(&w, name)
	}
	return w.Bytes(), nil
}

func (g *generator) emitEnum(w *bytes.Buffer, e *Enumeration) error {
	base, err := baseType(e.Type.Name)
	if err != nil {
		return err
	}
	comment(w, "", e.Name+": "+e.Documentation, e.Deprecated)
	fmt.Fprintf(w, "type %s %s\n\n", e.Name, base)
	fmt.Fprintf(w, "// The %s values.\nconst (\n", e.Name)
	for _, v := range e.Values {
		if v.Proposed {
			continue
		}
		name := e.Name + upperFirst(v.Name)
		if err := g.declare(name); err != nil {
			return err
		}
		lit := string(v.Value)
		if base == "string" {
			var s string
			if err := json.Unmarshal(v.Value, &s); err != nil {
				return fmt.Errorf("member %s: %w", v.Name, err)
			}
			lit = strconv.Quote(s)
		} else if _, err := strconv.ParseInt(lit, 10, 64); err != nil {
			return fmt.Errorf("member %s: value %s", v.Name, lit)
		}
		if v.Documentation != "" || v.Deprecated != "" {
			comment(w, "\t", name+": "+v.Documentation, v.Deprecated)
		}
		line := "\t" + name + " " + e.Name + " = " + lit
		if !fits(line) {
			line = "\t" + name + " " + e.Name + " = " + split(lit, "\t\t")
		}
		w.WriteString(line + "\n")
	}
	w.WriteString(")\n\n")
	return nil
}

func emitStruct(w *bytes.Buffer, d *structDecl) {
	comment(w, "", d.name+": "+d.doc, d.deprecated)
	if len(d.fields) == 0 {
		fmt.Fprintf(w, "type %s struct{}\n\n", d.name)
		return
	}
	fmt.Fprintf(w, "type %s struct {\n", d.name)
	for i, f := range d.fields {
		if f.doc != "" || f.deprecated != "" {
			if i > 0 {
				w.WriteString("\n")
			}
			comment(w, "\t", f.doc, f.deprecated)
		}
		fmt.Fprintf(w, "\t%s %s `json:%q`\n", f.goName, f.goType, f.tag)
	}
	w.WriteString("}\n\n")
	var empties []field
	for _, f := range d.fields {
		if f.empty != "" {
			empties = append(empties, f)
		}
	}
	if len(empties) == 0 {
		return
	}
	w.WriteString("// MarshalJSON writes a nil required list as an " +
		"empty one.\n")
	sig := "func (x " + d.name + ") MarshalJSON() ([]byte, error) {"
	if !fits(sig) {
		sig = "func (x " + d.name + ") MarshalJSON() (\n" +
			"\t[]byte, error,\n) {"
	}
	fmt.Fprintf(w, "%s\n\ttype plain %s\n\tp := plain(x)\n", sig,
		d.name)
	for _, f := range empties {
		set := "\t\tp." + f.goName + " = " + f.empty
		if !fits(set) {
			set = "\t\tp." + f.goName + " =\n\t\t\t" + f.empty
		}
		fmt.Fprintf(w, "\tif p.%s == nil {\n%s\n\t}\n", f.goName, set)
	}
	w.WriteString("\treturn json.Marshal(p)\n}\n\n")
}

func (g *generator) emitOr(w *bytes.Buffer, o *orDecl,
	shapes map[string]bool) error {
	var names, alts []string
	for i, it := range o.items {
		goT, err := g.goType(it, o.itemCtx[i])
		if err != nil {
			return err
		}
		names = append(names, goT)
		a, err := g.alt(it, o.itemCtx[i], shapes)
		if err != nil {
			return err
		}
		alts = append(alts, a)
	}
	text := o.name + " is one of " + strings.Join(names, ", ") + "."
	comment(w, "", text)
	if o.doc != "" {
		w.WriteString("//\n")
		comment(w, "", o.doc)
	}
	fmt.Fprintf(w, "type %s struct {\n", o.name)
	comment(w, "\t", "Value is nil (null) or a value of one of the "+
		"types above, not a pointer to one.")
	w.WriteString("\tValue any\n}\n\n")
	sig := "func (o " + o.name + ") MarshalJSON() ([]byte, error) {"
	if !fits(sig) {
		sig = "func (o " + o.name + ") MarshalJSON() (\n" +
			"\t[]byte, error,\n) {"
	}
	fmt.Fprintf(w, "// MarshalJSON writes Value; nil is null.\n%s\n"+
		"\treturn marshalOr(o.Value)\n}\n\n", sig)
	sig = "func (o *" + o.name + ") UnmarshalJSON(b []byte) error {"
	if !fits(sig) {
		sig = "func (o *" + o.name + ") UnmarshalJSON(\n" +
			"\tb []byte,\n) error {"
	}
	call := fmt.Sprintf("\tv, err := unmarshalOr(b, alts%s, %q)",
		o.name, o.name)
	if !fits(call) {
		call = fmt.Sprintf("\tv, err := unmarshalOr(\n\t\tb, alts%s,"+
			"\n\t\t%q,\n\t)", o.name, o.name)
	}
	fmt.Fprintf(w, "// UnmarshalJSON reads the alternative that matches "+
		"the JSON.\n%s\n%s\n\tif err != nil {\n\t\treturn err\n\t}\n"+
		"\to.Value = v\n\treturn nil\n}\n\n", sig, call)
	fmt.Fprintf(w, "var alts%s = []alt{\n", o.name)
	for _, a := range alts {
		writeAlt(w, a)
	}
	w.WriteString("}\n\n")
	return nil
}

// alt returns the Go expression of the alternative for item t.
func (g *generator) alt(t *Type, ctx string, shapes map[string]bool) (
	string, error) {
	goT, err := g.goType(t, ctx)
	if err != nil {
		return "", err
	}
	kinds, err := g.kinds(t)
	if err != nil {
		return "", err
	}
	parts := []string{"kinds: " + kinds}
	u := g.underlying(t)
	switch {
	case t.Kind == "literal":
		name := goT
		shapes[name] = true
		parts = append(parts, "shape: shape"+name)
	case u.Kind == "struct":
		shapes[u.Name] = true
		parts = append(parts, "shape: shape"+u.Name)
	case u.Kind == "or" && t.Kind == "reference":
		parts = append(parts, "sub: alts"+t.Name)
	case u.Kind == "or":
		return "", fmt.Errorf("anonymous nested or type in %s", ctx)
	case u.Kind == "array" && t.Kind == "array":
		el, err := g.alt(t.Element, ctx, shapes)
		if err != nil {
			return "", err
		}
		parts = append(parts, "elem: &alt"+el)
	}
	parts = append(parts, "decode: as["+goT+"]")
	return "{" + strings.Join(parts, ", ") + "}", nil
}

// writeAlt writes one element of an alts list, one field per line
// when it does not fit on one.
func writeAlt(w *bytes.Buffer, a string) { writeLit(w, "\t", "", a) }

// writeLit writes prefix+lit+"," at indent, where lit is a composite
// literal "{f1, f2, ...}", breaking it into one field per line (and
// recursing into nested literals) when the line is too long.
func writeLit(w *bytes.Buffer, indent, prefix, lit string) {
	line := indent + prefix + lit + ","
	// gofmt may pad a key ("elem:" to "kinds:" width) by up to 3.
	if pad := min(len(prefix), 3); fits(line + strings.Repeat(" ", pad)) {
		w.WriteString(line + "\n")
		return
	}
	inner := lit[1 : len(lit)-1]
	var fields []string
	depth, start := 0, 0
	for i := 0; i < len(inner); i++ {
		switch inner[i] {
		case '{', '[':
			depth++
		case '}', ']':
			depth--
		case ',':
			if depth == 0 {
				fields = append(fields, strings.TrimSpace(inner[start:i]))
				start = i + 1
			}
		}
	}
	fields = append(fields, strings.TrimSpace(inner[start:]))
	w.WriteString(indent + prefix + "{\n")
	for _, f := range fields {
		if k := strings.Index(f, "{"); k >= 0 && strings.HasSuffix(f, "}") {
			writeLit(w, indent+"\t", f[:k], f[k:])
			continue
		}
		w.WriteString(indent + "\t" + f + ",\n")
	}
	w.WriteString(indent + "},\n")
}

// split breaks a long quoted string into a concatenation of two
// halves, the second on its own line at indent. gofmt keeps a line
// break after a binary operator, where it would join "=" and a value.
func split(quoted, indent string) string {
	s, err := strconv.Unquote(quoted)
	if err != nil || len(s) < 2 {
		return quoted
	}
	cut := len(s) / 2
	if i := strings.LastIndexAny(s[:len(s)-1], "/."); i > 0 {
		cut = i + 1
	}
	return strconv.Quote(s[:cut]) + " +\n" + indent +
		strconv.Quote(s[cut:])
}

// fits reports whether line fits in 80 columns with tabs counted as 4,
// golines' default.
func fits(line string) bool {
	return len(line)+3*strings.Count(line, "\t") <= 80
}

// kinds returns the JSON kind mask expression of t.
func (g *generator) kinds(t *Type) (string, error) {
	switch u := g.underlying(t); u.Kind {
	case "any":
		return "kAny", nil
	case "struct", "map":
		return "kObject", nil
	case "array", "tuple":
		return "kArray", nil
	case "stringLiteral":
		return "kString", nil
	case "booleanLiteral":
		return "kBool", nil
	case "integerLiteral":
		return "kNumber", nil
	case "enum":
		return baseKind(g.enums[u.Name].Type.Name)
	case "base":
		return baseKind(u.Name)
	case "or":
		var ks []string
		for _, it := range u.Items {
			k, err := g.kinds(it)
			if err != nil {
				return "", err
			}
			if !slices.Contains(ks, k) {
				ks = append(ks, k)
			}
		}
		return strings.Join(ks, " | "), nil
	}
	return "", fmt.Errorf("no JSON kind for %s %s", t.Kind, t.Name)
}

func baseKind(name string) (string, error) {
	switch name {
	case "string", "DocumentUri", "URI":
		return "kString", nil
	case "integer", "uinteger", "decimal":
		return "kNumber", nil
	case "boolean":
		return "kBool", nil
	case "null":
		return "kNull", nil
	}
	return "", fmt.Errorf("base type %q has no JSON kind", name)
}

func (g *generator) emitShape(w *bytes.Buffer, name string) {
	var req, known, fixed []string
	for _, p := range g.shapes[name] {
		known = append(known, strconv.Quote(p.Name))
		if !p.Optional {
			req = append(req, strconv.Quote(p.Name))
		}
		if p.Type.Kind == "stringLiteral" {
			var v string
			if json.Unmarshal(p.Type.Value, &v) == nil {
				b, _ := json.Marshal(v)
				fixed = append(fixed, strconv.Quote(p.Name),
					strconv.Quote(string(b)))
			}
		}
	}
	fmt.Fprintf(w, "var shape%s = &shape{\n", name)
	list(w, "req", req)
	list(w, "known", known)
	list(w, "fixed", fixed)
	w.WriteString("}\n\n")
}

// list writes a []string field of a composite literal, wrapped to 80
// columns.
func list(w *bytes.Buffer, name string, items []string) {
	if len(items) == 0 {
		return
	}
	line := "\t" + name + ": []string{"
	if len(line)+len(strings.Join(items, ", "))+2 <= 76 {
		fmt.Fprintf(w, "%s%s},\n", line, strings.Join(items, ", "))
		return
	}
	w.WriteString(line + "\n")
	cur := "\t\t"
	for _, it := range items {
		if len(cur)+len(it)+2 > 72 && cur != "\t\t" {
			w.WriteString(strings.TrimRight(cur, " ") + "\n")
			cur = "\t\t"
		}
		cur += it + ", "
	}
	w.WriteString(strings.TrimRight(cur, " ") + "\n\t},\n")
}

var (
	linkRE  = regexp.MustCompile(`\{@link\s+([^\s}]+)(?:\s+([^}]*))?\}`)
	spaceRE = regexp.MustCompile(`\s+`)
)

// comment writes the first paragraph of doc as a Go comment wrapped to
// 80 columns (a tab counted as 8), then a Deprecated paragraph.
func comment(w *bytes.Buffer, indent, doc string, deprecated ...string) {
	para := func(s string) string {
		s = strings.TrimSpace(s)
		if i := strings.Index(s, "\n\n"); i >= 0 {
			s = s[:i]
		}
		s = linkRE.ReplaceAllStringFunc(s, func(m string) string {
			sub := linkRE.FindStringSubmatch(m)
			if strings.TrimSpace(sub[2]) != "" {
				return strings.TrimSpace(sub[2])
			}
			return sub[1]
		})
		return strings.TrimSpace(spaceRE.ReplaceAllString(s, " "))
	}
	text := para(doc)
	if strings.HasSuffix(text, ":") {
		text = strings.TrimSuffix(text, ":") + "."
	}
	width := 80 - 3 - 8*len(indent)
	wrap(w, indent, text, width)
	for _, d := range deprecated {
		if d = para(d); d != "" {
			if text != "" {
				w.WriteString(indent + "//\n")
			}
			wrap(w, indent, "Deprecated: "+d, width)
		}
	}
}

func wrap(w *bytes.Buffer, indent, text string, width int) {
	if text == "" {
		return
	}
	line := ""
	for word := range strings.FieldsSeq(text) {
		if line != "" && len(line)+1+len(word) > width {
			w.WriteString(indent + "// " + line + "\n")
			line = ""
		}
		if line != "" {
			line += " "
		}
		line += word
	}
	w.WriteString(indent + "// " + line + "\n")
}
